#include <iostream>
#include <string>

template <typename T>
struct ListNode {
    T data;
    ListNode<T>* nextPtr{nullptr};
    ListNode(const T& val) : data(val), nextPtr(nullptr) {}
};

template <typename T>
class SimpleList {
public:
    SimpleList() : firstPtr(nullptr), lastPtr(nullptr) {}
    ~SimpleList() {
        while (!isEmpty()) {
            T temp;
            removeFromFront(temp);
        }
    }

    bool isEmpty() const {
        return firstPtr == nullptr;
    }

    void insertAtFront(const T& val) {
        ListNode<T>* newPtr = getNewNode(val);
        if (isEmpty()) {
            firstPtr = lastPtr = newPtr;
        } else {
            newPtr->nextPtr = firstPtr;
            firstPtr = newPtr;
        }
    }

    void insertAtBack(const T& val) {
        ListNode<T>* newPtr = getNewNode(val);
        if (isEmpty()) {
            firstPtr = lastPtr = newPtr;
        } else {
            lastPtr->nextPtr = newPtr;
            lastPtr = newPtr;
        }
    }

    bool removeFromFront(T& val) {
        if (isEmpty()) return false;
        ListNode<T>* tempPtr = firstPtr;
        if (firstPtr == lastPtr) {
            firstPtr = lastPtr = nullptr;
        } else {
            firstPtr = firstPtr->nextPtr;
        }
        val = tempPtr->data;
        delete tempPtr;
        return true;
    }

    void print() const {
        if (isEmpty()) {
            std::cout << "The list is empty\n";
            return;
        }
        std::cout << "The list is: ";
        ListNode<T>* currentPtr = firstPtr;
        while (currentPtr != nullptr) {
            std::cout << currentPtr->data << ' ';
            currentPtr = currentPtr->nextPtr;
        }
        std::cout << "\n";
    }

private:
    ListNode<T>* firstPtr;
    ListNode<T>* lastPtr;

    ListNode<T>* getNewNode(const T& val) {
        return new ListNode<T>(val);
    }
};

int main() {
    SimpleList<int> list;
    list.insertAtFront(7);
    list.insertAtFront(12);
    list.insertAtBack(11);
    list.insertAtBack(5);
    list.print();
    return 0;
}

#include <iostream>

struct Node {
    int data;
    Node* next{nullptr};
    Node(int val) : data(val), next(nullptr) {}
};

class SinglyList {
public:
    Node* firstPtr{nullptr};
    Node* lastPtr{nullptr};

    ~SinglyList() {
        int val;
        while (removeFromFront(val));
    }

    void pushBack(int val) {
        Node* n = new Node(val);
        if (!firstPtr) {
            firstPtr = lastPtr = n;
        } else {
            lastPtr->next = n;
            lastPtr = n;
        }
    }

    bool removeFromFront(int& val) {
        if (!firstPtr) return false;
        Node* temp = firstPtr;
        if (firstPtr == lastPtr) {
            firstPtr = lastPtr = nullptr;
        } else {
            firstPtr = firstPtr->next;
        }
        val = temp->data;
        delete temp;
        return true;
    }

    bool removeFromBack(int& val) {
        if (!firstPtr) return false;
        Node* temp = lastPtr;
        if (firstPtr == lastPtr) {
            firstPtr = lastPtr = nullptr;
        } else {
            Node* cur = firstPtr;
            while (cur->next != lastPtr) {
                cur = cur->next;
            }
            lastPtr = cur;
            lastPtr->next = nullptr;
        }
        val = temp->data;
        delete temp;
        return true;
    }
};

int main() {
    SinglyList list;
    list.pushBack(12);
    list.pushBack(7);
    list.pushBack(11);
    list.pushBack(5);

    int val;
    if (list.removeFromFront(val)) {
        std::cout << "Removed front: " << val << "\n";
    }
    if (list.removeFromBack(val)) {
        std::cout << "Removed back: " << val << "\n";
    }

    std::cout << "Remaining nodes: ";
    Node* cur = list.firstPtr;
    while (cur != nullptr) {
        std::cout << cur->data << " ";
        cur = cur->next;
    }
    std::cout << "\n";
    return 0;
}
